<template>
  <div>
    <PageHeader title="推广信息录入" subtitle="集中维护电话、邮箱及扩展推广资料，支持官方模板批量导入。">
      <div class="header-actions"><button class="layui-btn monitor-secondary" type="button" :disabled="downloading" @click="downloadTemplate"><i class="layui-icon layui-icon-download-circle"></i>{{ downloading ? '下载中' : '下载模板' }}</button><label class="layui-btn monitor-secondary file-button"><i class="layui-icon layui-icon-upload-drag"></i>{{ importing ? '导入中' : '批量导入' }}<input type="file" accept=".xlsx" :disabled="importing" @change="importFile"></label><button class="layui-btn monitor-primary" type="button" @click="openCreate"><i class="layui-icon layui-icon-add-1"></i>新增信息</button></div>
    </PageHeader>

    <section class="panel query-panel target-panel">
      <div class="query-toolbar"><h2>推广目标</h2><form class="query-filters" @submit.prevent="search"><input v-model.trim="query.keyword" class="layui-input" aria-label="名称电话或邮箱" placeholder="名称、电话或邮箱"><select v-model="query.sourceType" class="layui-select" aria-label="数据来源"><option value="">全部来源</option><option value="MANUAL">手工录入</option><option value="EXCEL_IMPORT">Excel 导入</option></select><select v-model="query.status" class="layui-select" aria-label="推广状态"><option value="">全部状态</option><option value="1">可推广</option><option value="0">已停用</option></select><button class="layui-btn monitor-primary" :disabled="loading">查询</button><button class="layui-btn monitor-secondary" type="button" @click="reset">重置</button></form></div>
      <div v-if="loading" class="loading-state">正在查询推广信息…</div><div v-else-if="!result.list.length" class="empty-state">暂无推广信息，可新增或下载模板批量导入。</div>
      <template v-else><div class="table-wrap"><table class="layui-table monitor-table target-table"><thead><tr><th>名称</th><th>电话</th><th>邮箱</th><th>来源</th><th>状态</th><th>更新时间</th><th>备注</th><th>操作</th></tr></thead><tbody><tr v-for="item in result.list" :key="item.id"><td><strong>{{ item.name }}</strong></td><td class="number">{{ item.phone || '—' }}</td><td>{{ item.email || '—' }}</td><td><span>{{ item.sourceType === 'EXCEL_IMPORT' ? 'Excel 导入' : '手工录入' }}</span><small v-if="item.importBatchNo">{{ item.importBatchNo }}</small></td><td><span :class="['tag', Number(item.status) === 1 ? 'success' : '']">{{ Number(item.status) === 1 ? '可推广' : '已停用' }}</span></td><td class="number">{{ dateTime(item.updatedAt) }}</td><td class="remark-cell" :title="item.remark || ''">{{ item.remark || '—' }}</td><td><div class="row-actions"><button class="layui-btn layui-btn-xs monitor-secondary" type="button" @click="openEdit(item)">编辑</button><button class="layui-btn layui-btn-xs status-toggle" :class="Number(item.status) === 1 ? 'status-disable' : 'status-enable'" type="button" :disabled="statusChangingId === item.id" :aria-label="`${Number(item.status) === 1 ? '停用' : '启用'}${item.name}`" @click="toggleStatus(item)">{{ statusChangingId === item.id ? '处理中…' : (Number(item.status) === 1 ? '停用' : '启用') }}</button><button class="layui-btn layui-btn-xs monitor-danger" type="button" @click="openDelete(item)">删除</button></div></td></tr></tbody></table></div><AppPagination :page-no="result.pageNo" :page-size="result.pageSize" :total="result.total" @change="changePage" /></template>
    </section>

    <AppModal v-model="editorVisible" :title="editingId ? '编辑推广信息' : '新增推广信息'" confirm-text="保存" :loading="submitting" @confirm="save"><form class="target-form" @submit.prevent="save"><div class="editor-grid"><div class="field field-span-2"><label for="target-name">名称 <b>*</b></label><input id="target-name" ref="nameInput" v-model.trim="form.name" class="layui-input" maxlength="100"></div><div class="field"><label for="target-phone">电话</label><input id="target-phone" v-model.trim="form.phone" type="tel" class="layui-input" maxlength="32"></div><div class="field"><label for="target-email">邮箱</label><input id="target-email" v-model.trim="form.email" type="email" class="layui-input" maxlength="254"></div><p class="helper field-span-2">电话和邮箱至少填写一项。</p><fieldset class="field status-field field-span-2"><legend>状态</legend><div class="status-radio-group" role="radiogroup" aria-label="推广状态"><label :class="{ active: Number(form.status) === 1 }"><input v-model.number="form.status" type="radio" name="target-status" :value="1"><span>可推广</span></label><label :class="{ active: Number(form.status) === 0 }"><input v-model.number="form.status" type="radio" name="target-status" :value="0"><span>停用</span></label></div></fieldset><div class="field field-span-2"><label for="target-remark">备注</label><textarea id="target-remark" v-model.trim="form.remark" class="layui-textarea" maxlength="500"></textarea></div><p v-if="formError" class="form-error field-span-2" role="alert">{{ formError }}</p></div></form></AppModal>
    <AppModal v-model="deleteVisible" title="确认删除推广信息？" confirm-text="删除" :danger="true" :loading="submitting" @confirm="remove"><p>删除后该目标不会再进入推广候选范围。</p></AppModal>
    <AppModal v-model="importVisible" title="批量导入结果" confirm-text="知道了" @confirm="importVisible=false"><div v-if="importResult" class="import-result"><div><strong>{{ importResult.successRows }}</strong><span>成功</span></div><div><strong>{{ importResult.failureRows }}</strong><span>失败</span></div></div><ul v-if="importResult?.failures?.length" class="failure-list"><li v-for="item in importResult.failures.slice(0,20)" :key="item.rowNumber">第 {{ item.rowNumber }} 行 {{ item.name || '未命名' }}：{{ item.reason }}</li></ul></AppModal>
    <AppToast :message="toastMessage" :type="toastType" />
  </div>
</template>
<script>
import PageHeader from '@/components/PageHeader.vue'; import AppPagination from '@/components/AppPagination.vue'; import AppModal from '@/components/AppModal.vue'; import AppToast from '@/components/AppToast.vue'; import feedback from '@/mixins/feedback'; import { promotionApi } from '@/api/monitor';
const emptyForm=()=>({name:'',phone:'',email:'',status:1,remark:''});
export default { name:'PromotionTargetPage',components:{PageHeader,AppPagination,AppModal,AppToast},mixins:[feedback],data:()=>({query:{keyword:'',sourceType:'',status:'',pageNo:1,pageSize:10},result:{list:[],pageNo:1,pageSize:10,total:0},loading:false,downloading:false,importing:false,submitting:false,statusChangingId:null,editorVisible:false,deleteVisible:false,importVisible:false,editingId:null,selected:null,form:emptyForm(),formError:'',importResult:null}),mounted(){this.load();},methods:{
  /** 按当前筛选读取数据库分页结果。 */ async load(){this.loading=true;try{const params=Object.fromEntries(Object.entries(this.query).filter(([,v])=>v!==''));this.result=await promotionApi.targets(params);}catch(e){this.errorMessage(e);}finally{this.loading=false;}},search(){this.query.pageNo=1;this.load();},reset(){Object.assign(this.query,{keyword:'',sourceType:'',status:'',pageNo:1});this.load();},changePage(pageNo){this.query.pageNo=pageNo;this.load();},
  /** 下载 Blob 并及时释放浏览器对象地址。 */ async downloadTemplate(){this.downloading=true;try{const blob=await promotionApi.template();const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download='销售推广信息导入模板.xlsx';link.click();URL.revokeObjectURL(url);}catch(e){this.errorMessage(e);}finally{this.downloading=false;}},
  /** 选择文件后立即上传，允许再次选择同名文件。 */ async importFile(event){const file=event.target.files?.[0];event.target.value='';if(!file)return;this.importing=true;try{this.importResult=await promotionApi.importTargets(file);this.importVisible=true;await this.load();}catch(e){this.errorMessage(e);}finally{this.importing=false;}},
  openCreate(){this.editingId=null;this.form=emptyForm();this.formError='';this.editorVisible=true;this.$nextTick(()=>this.$refs.nameInput?.focus());},openEdit(item){this.editingId=item.id;this.form={...emptyForm(),...item};this.formError='';this.editorVisible=true;},
  /** 先执行页面级必填校验，再交由后端统一校验格式与长度。 */ async save(){if(this.submitting)return;this.formError=!this.form.name?'请填写名称':(!this.form.phone&&!this.form.email?'电话和邮箱至少填写一项':'');if(this.formError)return;this.submitting=true;try{if(this.editingId)await promotionApi.updateTarget(this.editingId,this.form);else await promotionApi.createTarget(this.form);this.editorVisible=false;this.notify('推广信息已保存');await this.load();}catch(e){this.formError=e.message;}finally{this.submitting=false;}},
  /**
   * 切换单个推广目标的可用状态。
   * 列表行操作复用现有完整更新接口，保留名称、联系方式等原有业务数据，仅反转 status。
   * 请求期间记录当前目标 ID，用于防止重复点击并在对应按钮上展示处理中反馈。
   * 成功后直接合并接口返回值到当前响应式列表行，不重新触发整表加载，避免用户只切换一个状态时页面闪烁。
   * @param {Object} item 列表中的推广目标完整数据。
   * @returns {Promise<void>} 更新成功后就地刷新当前行状态。
   */
  async toggleStatus(item){if(this.statusChangingId!==null)return;this.statusChangingId=item.id;const nextStatus=Number(item.status)===1?0:1;try{const updated=await promotionApi.updateTarget(item.id,{...item,status:nextStatus});Object.assign(item,updated||{}, {status:nextStatus});this.notify(nextStatus===1?'推广目标已启用':'推广目标已停用');}catch(e){this.errorMessage(e);}finally{this.statusChangingId=null;}},
  /** 确认后直接请求软删除当前推广目标，该业务不再收集删除原因。 */
  openDelete(item){this.selected=item;this.deleteVisible=true;},async remove(){if(this.submitting)return;this.submitting=true;try{await promotionApi.removeTarget(this.selected.id);this.deleteVisible=false;this.notify('推广信息已删除');await this.load();}catch(e){this.errorMessage(e);}finally{this.submitting=false;}},dateTime(v){return v?String(v).replace('T',' ').slice(0,16):'—';}
}};
</script>
<style scoped>
.header-actions,.row-actions{display:flex;align-items:center;gap:8px}.row-actions{flex-wrap:nowrap;white-space:nowrap}.row-actions .monitor-danger{border-color:var(--danger);color:#fff;background:var(--danger);transition:background-color .2s ease,border-color .2s ease}.row-actions .monitor-danger:hover{border-color:#991b1b;color:#fff;background:#991b1b}.file-button{position:relative;overflow:hidden}.file-button input{position:absolute;inset:0;opacity:0;cursor:pointer}.target-panel{padding:22px}.query-toolbar{display:flex;align-items:center;justify-content:space-between;gap:16px;flex-wrap:wrap}.query-toolbar h2{margin:0 0 16px;font-size:18px}.query-filters{display:flex;align-items:center;gap:10px;flex-wrap:wrap;margin-left:auto}.query-filters .layui-input{width:220px}.query-filters .layui-select{width:130px;height:38px;border:1px solid var(--border);border-radius:4px}.target-table{min-width:1240px}.target-table small{display:block;max-width:220px;color:var(--muted);font-size:12px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.remark-cell{max-width:240px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.status-toggle{color:#fff;transition:background-color .2s ease,border-color .2s ease}.status-disable{border-color:#f59e0b;background:#f59e0b}.status-disable:hover{border-color:#d97706;color:#fff;background:#d97706}.status-enable{border-color:var(--success);background:var(--success)}.status-enable:hover{border-color:#065f46;color:#fff;background:#065f46}.status-toggle:disabled{cursor:not-allowed;opacity:.5}.editor-grid{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);column-gap:16px}.field{min-width:0;margin-bottom:14px}.field-span-2{grid-column:1 / -1}.target-form .field>label,.status-field>legend{display:block;min-height:20px;margin:0 0 6px;padding:0;font-weight:600;line-height:20px}.field b{color:var(--danger)}.target-form .layui-input,.target-form .layui-textarea{box-sizing:border-box;width:100%;margin:0}.layui-textarea{min-height:86px;border-color:var(--border);border-radius:5px}.helper{margin:-8px 0 14px;color:var(--muted);font-size:12px}.status-field{min-width:0;margin-inline:0;padding:0;border:0}.status-radio-group{display:grid;grid-template-columns:1fr 1fr;gap:12px}.status-radio-group label{display:flex;min-height:40px;box-sizing:border-box;align-items:center;gap:8px;margin:0;padding:0 14px;border:1px solid var(--border);border-radius:5px;background:var(--surface);cursor:pointer;transition:border-color .2s ease,background-color .2s ease}.status-radio-group label.active{border-color:var(--primary);background:var(--surface-soft)}.status-radio-group input{margin:0;accent-color:var(--primary)}.status-radio-group label:focus-within{outline:2px solid var(--primary);outline-offset:2px}.form-error{color:var(--danger)}.import-result{display:grid;grid-template-columns:1fr 1fr;gap:12px}.import-result div{display:flex;flex-direction:column;align-items:center;padding:18px;background:var(--background);border-radius:8px}.import-result strong{font-size:26px}.failure-list{max-height:240px;margin:14px 0 0;padding-left:22px;overflow:auto;color:var(--danger)}@media(max-width:720px){.header-actions,.query-filters{width:100%;flex-direction:column;align-items:stretch}.header-actions>*{width:100%;text-align:center}.query-filters .layui-input,.query-filters .layui-select{width:100%;min-height:44px}.editor-grid{grid-template-columns:1fr}.field-span-2{grid-column:auto}.status-radio-group{grid-template-columns:1fr 1fr}}
</style>
